#include <net-snmp/net-snmp-config.h>
#include <net-snmp/net-snmp-includes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

int LLVMFuzzerInitialize(int *argc, char ***argv) {
    if (getenv("NETSNMP_DEBUGGING") != NULL) {
        /*
         * Turn on all debugging, to help understand what
         * bits of the parser are running.
         */
        snmp_enable_stderrlog();
        snmp_set_do_debugging(1);
        debug_register_tokens("");
    }
    return 0;
}

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    if (size == 0) {
        return 0;
    }

    const uint8_t decider = *data;
    data++;
    size--;

    // Allocate a large destination buffer
    char *dst_buf = malloc((size*sizeof(oid)));
    size_t len = size;

    char *src_buf = malloc(size+1);
    src_buf[size] = '\0';
    memcpy(src_buf, data, size);
    read_config_read_memory(decider, src_buf, dst_buf, &len);
    free(dst_buf);
    free(src_buf);

    return 0;
}

